<script lang="ts">
  import { onMount } from "svelte";
  import { IconActivity, IconBell, IconBolt, IconChecks, IconFolders, IconGitBranch, IconHistory, IconLayoutSidebarLeftCollapse, IconPlayerPlay, IconPlugConnected, IconSearch, IconSettings, IconSparkles } from "@tabler/icons-svelte";
  import { createDesktopBackend, type DesktopSnapshot } from "../../lib/desktop-backend";
  import { initialRoute, migrateWorkspaceRecents, persistRoute, routeFromDeepLink, ROUTE_LABELS, type AppRoute } from "../../lib/navigation.svelte";
  import OperationsScreen from "./OperationsScreen.svelte";
  import FlowScreen from "./FlowScreen.svelte";
  import CollectionScreen from "./CollectionScreen.svelte";
  import FocusScreen from "./FocusScreen.svelte";
  import { onPytxoDeepLink } from "../../lib/ipc";

  let { routeOverride = null, previewState = "default" }: { routeOverride?: AppRoute | null; previewState?: "default" | "loading" | "empty" | "offline" | "error" } = $props();

  const backend = createDesktopBackend();
  let route = $state<AppRoute>("operations");
  let snapshot = $state<DesktopSnapshot>({ domains: [], runs: [], agents: [], approvals: [], fleets: [] });
  let loading = $state(true);
  let commandOpen = $state(false);
  let loadMessage = $state("");
  let recents = $state<ReturnType<typeof migrateWorkspaceRecents>>([]);

  const primary = [
    { route: "operations" as const, label: "Operations", icon: IconActivity },
    { route: "workspaces" as const, label: "Workspaces", icon: IconFolders },
    { route: "runs" as const, label: "Runs", icon: IconPlayerPlay },
    { route: "flow" as const, label: "Flow", icon: IconSparkles },
    { route: "approvals" as const, label: "Approvals", icon: IconChecks },
  ];
  const system = [
    { route: "integrations" as const, label: "Integrations", icon: IconPlugConnected },
    { route: "settings" as const, label: "Settings", icon: IconSettings },
  ];

  function navigate(next: AppRoute) {
    route = next;
    persistRoute(next);
  }

  onMount(() => {
    let disposed = false;
    let deepLinkUnlisten: (() => void) | null = null;
    route = routeOverride ?? initialRoute();
    const onHashChange = () => { if (!routeOverride) route = initialRoute(); };
    const handleDeepLink = (value: string) => { const target = routeFromDeepLink(value); if (target) navigate(target); };
    const onBrowserDeepLink = (event: Event) => handleDeepLink((event as CustomEvent<string>).detail);
    window.addEventListener("hashchange", onHashChange);
    window.addEventListener("pytxo-deep-link", onBrowserDeepLink);
    recents = migrateWorkspaceRecents();
    if (previewState === "loading") return () => { disposed = true; window.removeEventListener("hashchange", onHashChange); window.removeEventListener("pytxo-deep-link", onBrowserDeepLink); };
    if (previewState === "empty" || previewState === "offline") {
      loading = false;
      if (previewState === "offline") loadMessage = "Offline · showing locally available workspace state";
      return () => { disposed = true; window.removeEventListener("hashchange", onHashChange); window.removeEventListener("pytxo-deep-link", onBrowserDeepLink); };
    }
    if (previewState === "error") {
      loading = false;
      loadMessage = "Pytxo could not reach the local hypervisor. Retry when the service is available.";
      return () => { disposed = true; window.removeEventListener("hashchange", onHashChange); window.removeEventListener("pytxo-deep-link", onBrowserDeepLink); };
    }
    void (async () => {
      try { snapshot = await backend.loadSnapshot(); } finally { loading = false; }
      try {
        const unlisten = await onPytxoDeepLink(handleDeepLink);
        if (disposed) unlisten(); else deepLinkUnlisten = unlisten;
      } catch { /* Browser and Storybook use the preview backend without Tauri events. */ }
    })();
    return () => { disposed = true; deepLinkUnlisten?.(); window.removeEventListener("hashchange", onHashChange); window.removeEventListener("pytxo-deep-link", onBrowserDeepLink); };
  });
</script>

<div class="desktop2">
  <aside class="sidebar">
    <div class="brand"><div class="brand-mark"><IconBolt size={17} /></div><div><strong>Pytxo</strong><span>Desktop</span></div><button aria-label="Collapse sidebar"><IconLayoutSidebarLeftCollapse size={16} /></button></div>
    <button class="command-trigger" onclick={() => (commandOpen = true)}><IconSearch size={15} /><span>Search or command</span><kbd>⌘ K</kbd></button>
    <nav aria-label="Primary"><p>Workspace</p>{#each primary as item}<a href={`#/${item.route}`} class:active={route === item.route} onclick={(event) => { event.preventDefault(); navigate(item.route); }}><item.icon size={17} stroke={1.7} /><span>{item.label}</span>{#if item.route === "approvals" && snapshot.approvals.length}<b>{snapshot.approvals.length}</b>{/if}</a>{/each}</nav>
    {#if recents.length}<div class="recents"><p>Recent</p>{#each recents.slice(0, 4) as recent}<button onclick={() => navigate("workspaces")}><i></i><span>{recent.label}</span></button>{/each}</div>{/if}
    <nav aria-label="System" class="system-nav"><p>System</p>{#each system as item}<a href={`#/${item.route}`} class:active={route === item.route} onclick={(event) => { event.preventDefault(); navigate(item.route); }}><item.icon size={17} stroke={1.7} /><span>{item.label}</span></a>{/each}</nav>
    <div class="sidebar-footer"><button><span class="avatar">MB</span><span><strong>Matt Bacon</strong><small>Core · Local</small></span><IconSettings size={15} /></button></div>
  </aside>

  <main>
    <div class="app-bar"><div class="breadcrumbs"><span>Pytxo</span><i>/</i><strong>{ROUTE_LABELS[route]}</strong></div><div class="app-actions"><span class="connection"><i></i> Local hypervisor</span><button aria-label="Activity history"><IconHistory size={17} /></button><button aria-label="Notifications"><IconBell size={17} />{#if snapshot.approvals.length}<i></i>{/if}</button></div></div>
    <div class="content">
      {#if loadMessage}<div class:error-banner={previewState === "error"} class="status-banner">{loadMessage}</div>{/if}
      {#if loading}<div class="loading-state"><div></div><div></div><div></div></div>
      {:else if route === "operations"}<OperationsScreen {snapshot} onRoute={navigate} />
      {:else if route === "flow"}<FlowScreen {backend} domains={snapshot.domains} />
      {:else if route === "topology-focus" || route === "run-review"}<FocusScreen mode={route} onBack={() => navigate("runs")} />
      {:else}<CollectionScreen {route} {snapshot} {backend} onRoute={navigate} />{/if}
    </div>
  </main>

  {#if commandOpen}<dialog open class="command-backdrop" aria-label="Command menu" onclick={(event) => { if (event.target === event.currentTarget) commandOpen = false; }}><section class="command-menu"><label><IconSearch size={18} /><input placeholder="Type a command or search…" aria-label="Command search" /></label><p>Navigate</p>{#each primary as item}<button onclick={() => { navigate(item.route); commandOpen = false; }}><item.icon size={16} />{item.label}<span>Go to</span></button>{/each}</section></dialog>{/if}
</div>

